use tower::util::ServiceExt;
# #[cfg(feature = "util")]
use tower::{load::Load, Service};
# #[cfg(feature = "util")]
async fn simple_balance<S1, S2, R>(
    svc1: &mut S1,
    svc2: &mut S2,
    request: R
) -> Result<S1::Response, S1::Error>
where
    S1: Load + Service<R>,
    S2: Load<Metric = S1::Metric> + Service<R, Response = S1::Response, Error = S1::Error>
