use indenter::indented;
use miette::{Diagnostic, ReportHandler};

pub struct Handler;

impl ReportHandler for Handler {
    fn debug(
        &self,
        error: &dyn Diagnostic,
        f: &mut core::fmt::Formatter<'_>,
    ) -> core::fmt::Result {
        use core::fmt::Write as _;

        if f.alternate() {
            return core::fmt::Debug::fmt(error, f);
        }

        write!(f, "{}", error)?;

        Ok(())
    }
}

